180→// parseMessage extracts and parses the "message" field from a transcript line.
181→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
182→	msgRaw, ok := raw["message"]
183→	if ok {
184→		var msg map[string]json.RawMessage
185→		if json.Unmarshal(msgRaw, &msg) == nil {
186→			return msg
187→		}
188→	}
189→
190→	// Native Gemini transcript entries store id/content at top-level
191→	// rather than inside a nested "message" object.
192→	msg := make(map[string]json.RawMessage, 2)
193→	if v, has := raw["id"]; has {
194→		msg["id"] = v
195→	}
196→	if v, has := raw["content"]; has {
197→		msg["content"] = v
198→	}
199→	if len(msg) == 0 {
200→		return nil
201→	}
202→	return msg
203→}
