  2→
  3→import (
  4→	"bufio"
  5→	"bytes"
  6→	"encoding/json"
  7→	"fmt"
  8→	"io"
  9→	"strings"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/textutil"
 12→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 13→)
 14→
 15→// userAliases maps transcript type/role values to the canonical "user" kind.
 16→var userAliases = map[string]bool{
 17→	transcript.TypeUser: true,
 18→	"human":             true,
 19→}
 20→
 21→// assistantAliases maps transcript type/role values to the canonical "assistant" kind.
 22→var assistantAliases = map[string]bool{
 23→	transcript.TypeAssistant: true,
 24→}
 25→
 26→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 27→// transcript line. It checks the "type" field, then falls back to "role".
 28→// Returns "" for unrecognised or dropped entries.
 29→func normalizeKind(raw map[string]json.RawMessage) string {
 30→	kind := unquote(raw["type"])
 31→	if kind == "" {
 32→		kind = unquote(raw["role"])
 33→	}
 34→
 35→	if droppedTypes[kind] {
 36→		return ""
 37→	}
 38→	if userAliases[kind] {
 39→		return transcript.TypeUser
 40→	}
 41→	if assistantAliases[kind] {
 42→		return transcript.TypeAssistant
 43→	}
 44→	return ""
 45→}
 46→
 47→// compactJSONL converts JSONL content (Claude Code, Cursor, Factory AI Droid)
 48→// into the compact transcript format, one line at a time.
 49→func compactJSONL(content []byte, opts Options) ([]byte, error) {
 50→	meta := newCompactMeta(opts)
 51→	reader := bufio.NewReader(bytes.NewReader(content))
 52→	var result []byte
 53→
 54→	for {
 55→		lineBytes, err := reader.ReadBytes('\n')
 56→		if err != nil && err != io.EOF {
 57→			return nil, fmt.Errorf("reading JSONL line: %w", err)
 58→		}
 59→
 60→		if len(bytes.TrimSpace(lineBytes)) > 0 {
 61→			outputLines := convertLine(lineBytes, meta)
 62→			for _, ol := range outputLines {
 63→				result = append(result, ol...)
 64→				result = append(result, '\n')
 65→			}
 66→		}
 67→
 68→		if err == io.EOF {
 69→			break
 70→		}
 71→	}
 72→
 73→	return result, nil
 74→}
 75→
 76→// convertLine converts a single full.jsonl line into zero or more transcript.jsonl lines.
 77→func convertLine(lineBytes []byte, meta compactMeta) [][]byte {
 78→	var raw map[string]json.RawMessage
 79→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
 80→		return nil
 81→	}
 82→
 83→	raw = unwrapEnvelope(raw)
 84→
 85→	switch normalizeKind(raw) {
 86→	case transcript.TypeAssistant:
 87→		return convertAssistant(raw, meta)
 88→	case transcript.TypeUser:
 89→		return convertUser(raw, meta)
 90→	default:
 91→		return nil
 92→	}
 93→}
 94→
 95→func convertAssistant(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
 96→	var id, content json.RawMessage
 97→	if msg := parseMessage(raw); msg != nil {
 98→		id = msg["id"]
 99→		if contentRaw, ok := msg["content"]; ok {
100→			content = stripAssistantContent(contentRaw)
101→		}
102→	}
103→
104→	b := marshalOrdered(
105→		"v", meta.v,
106→		"agent", meta.agent,
107→		"cli_version", meta.cliVersion,
108→		"type", mustMarshal(transcript.TypeAssistant),
109→		"ts", raw["timestamp"],
110→		"id", id,
111→		"content", content,
112→	)
113→	if b == nil {
114→		return nil
115→	}
116→	return [][]byte{b}
117→}
118→
119→func convertUser(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
120→	var lines [][]byte
121→	ts := raw["timestamp"]
122→
123→	var textContent string
124→	var toolResults []toolResultEntry
125→
126→	if msg := parseMessage(raw); msg != nil {
127→		if contentRaw, ok := msg["content"]; ok {
128→			textContent, toolResults = extractUserContent(contentRaw)
129→		}
130→	}
131→
132→	b := marshalOrdered(
133→		"v", meta.v,
134→		"agent", meta.agent,
135→		"cli_version", meta.cliVersion,
136→		"type", mustMarshal(transcript.TypeUser),
137→		"ts", ts,
138→		"content", mustMarshal(textContent),
139→	)
140→	if b != nil {
141→		lines = append(lines, b)
142→	}
143→
144→	// full.jsonl has a single toolUseResult per user entry, not one per tool_use_id.
145→	// When there are multiple tool_result blocks, each user_tool_result line gets the
146→	// same minimized result — a known limitation of the source format.
147→	var minimizedResult json.RawMessage
148→	if turRaw, ok := raw["toolUseResult"]; ok {
149→		minimizedResult = minimizeToolUseResult(turRaw)
150→	}
151→
152→	for _, tr := range toolResults {
153→		result := minimizedResult
154→		if result == nil {
155→			result = mustMarshal(map[string]interface{}{})
156→		}
157→
158→		b := marshalOrdered(
159→			"v", meta.v,
160→			"agent", meta.agent,
161→			"cli_version", meta.cliVersion,
162→			"type", mustMarshal("user_tool_result"),
163→			"ts", ts,
164→			"tool_use_id", mustMarshal(tr.toolUseID),
165→			"result", result,
166→		)
167→		if b != nil {
168→			lines = append(lines, b)
169→		}
170→	}
171→
172→	return lines
173→}
174→
175→type toolResultEntry struct {
176→	toolUseID string
177→}
178→
179→// parseMessage extracts and parses the "message" field from a transcript line.
180→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
181→	msgRaw, ok := raw["message"]
182→	if ok {
183→		var msg map[string]json.RawMessage
184→		if json.Unmarshal(msgRaw, &msg) == nil {
185→			return msg
186→		}
187→	}
188→
189→	// Some formats store id/content at top-level rather than inside a
190→	// nested "message" object. Fall back to extracting them directly.
191→	msg := make(map[string]json.RawMessage, 2)
192→	if v, has := raw["id"]; has {
193→		msg["id"] = v
194→	}
195→	if v, has := raw["content"]; has {
196→		msg["content"] = v
197→	}
198→	if len(msg) == 0 {
199→		return nil
200→	}
201→	return msg
202→}
203→
204→// extractUserContent separates user message content into text and tool_result entries.
205→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
206→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
207→	var str string
208→	if json.Unmarshal(contentRaw, &str) == nil {
209→		return textutil.StripIDEContextTags(str), nil
210→	}
211→
212→	var blocks []map[string]json.RawMessage
213→	if json.Unmarshal(contentRaw, &blocks) != nil {
214→		return "", nil
215→	}
216→
217→	var texts []string
218→	var toolResults []toolResultEntry
219→
220→	for _, block := range blocks {
221→		blockType := unquote(block["type"])
222→
223→		if blockType == "tool_result" {
224→			toolResults = append(toolResults, toolResultEntry{
225→				toolUseID: unquote(block["tool_use_id"]),
226→			})
227→			continue
228→		}
229→
230→		if blockType == transcript.ContentTypeText {
231→			stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
232→			if stripped != "" {
233→				texts = append(texts, stripped)
234→			}
235→		}
236→	}
237→
238→	return strings.Join(texts, "\n\n"), toolResults
239→}
240→
241→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
242→	var str string
243→	if json.Unmarshal(contentRaw, &str) == nil {
244→		return contentRaw
245→	}
246→
247→	var blocks []map[string]json.RawMessage
248→	if json.Unmarshal(contentRaw, &blocks) != nil {
249→		return contentRaw
250→	}
251→
252→	result := make([]map[string]json.RawMessage, 0, len(blocks))
253→	for _, block := range blocks {
254→		blockType := unquote(block["type"])
255→
256→		if blockType == "thinking" || blockType == "redacted_thinking" {
257→			continue
258→		}
259→
260→		if blockType == transcript.ContentTypeToolUse {
261→			stripped := make(map[string]json.RawMessage)
262→			copyField(stripped, block, "type")
263→			copyField(stripped, block, "id")
264→			copyField(stripped, block, "name")
265→			copyField(stripped, block, "input")
266→			result = append(result, stripped)
267→			continue
268→		}
269→
270→		result = append(result, block)
271→	}
272→
273→	b, err := json.Marshal(result)
274→	if err != nil {
275→		return contentRaw
276→	}
277→	return b
278→}
279→
280→// minimizeToolUseResult keeps only fields needed for replaying tool calls
281→// (type, file metadata, error, answers). Output text and other verbose
282→// fields are dropped to reduce transcript size.
283→func minimizeToolUseResult(raw json.RawMessage) json.RawMessage {
284→	var obj map[string]json.RawMessage
285→	if json.Unmarshal(raw, &obj) != nil {
286→		return raw
287→	}
288→
289→	return marshalOrdered(
290→		"type", obj["type"],
291→		"file", obj["file"],
292→		"error", obj["error"],
293→		"answers", obj["answers"],
294→	)
295→}
