179→// parseMessage extracts and parses the "message" field from a transcript line.
180→// All JSONL agents (Claude Code, Cursor, Factory AI Droid) nest content inside
181→// a "message" object.
182→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
183→	msgRaw, ok := raw["message"]
