194→// extractUserContent separates user message content into text and tool_result entries.
195→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
196→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
197→	var str string
198→	if json.Unmarshal(contentRaw, &str) == nil {
199→		return textutil.StripIDEContextTags(str), nil
200→	}
201→
202→	var blocks []map[string]json.RawMessage
203→	if json.Unmarshal(contentRaw, &blocks) != nil {
204→		return "", nil
205→	}
206→
207→	var texts []string
208→	var toolResults []toolResultEntry
209→
210→	for _, block := range blocks {
211→		blockType := unquote(block["type"])
212→
213→		if blockType == "tool_result" {
214→			toolResults = append(toolResults, toolResultEntry{
215→				toolUseID: unquote(block["tool_use_id"]),
216→			})
217→			continue
218→		}
219→
220→		if blockType == transcript.ContentTypeText {
221→			stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
222→			if stripped != "" {
223→				texts = append(texts, stripped)
224→			}
225→		}
226→	}
227→
228→	return strings.Join(texts, "\n\n"), toolResults
