237→	var blocks []map[string]json.RawMessage
238→	if json.Unmarshal(contentRaw, &blocks) != nil {
239→		return contentRaw
240→	}
241→
242→	result := make([]map[string]json.RawMessage, 0, len(blocks))
243→	for _, block := range blocks {
244→		blockType := unquote(block["type"])
245→
246→		if blockType == "thinking" || blockType == "redacted_thinking" {
247→			continue
248→		}
