250→		if blockType == transcript.ContentTypeToolUse {
251→			stripped := make(map[string]json.RawMessage)
252→			copyField(stripped, block, "type")
253→			copyField(stripped, block, "id")
254→			copyField(stripped, block, "name")
255→			copyField(stripped, block, "input")
256→			result = append(result, stripped)
