270→// minimizeToolUseResult keeps only fields needed for replaying tool calls
271→// (type, file metadata, error, answers). Output text and other verbose
272→// fields are dropped to reduce transcript size.
273→func minimizeToolUseResult(raw json.RawMessage) json.RawMessage {
