  1→// Package compact converts full.jsonl transcripts into a normalized,
  2→// compact transcript.jsonl format. Each agent format (Claude Code JSONL,
  3→// OpenCode JSON, Gemini, Factory AI Droid) has its own converter file;
  4→// this file holds the shared entry point and helper utilities.
  5→package compact
  6→
  7→import (
  8→	"bytes"
  9→	"encoding/json"
 10→)
 11→
 12→// droppedTypes are entry types that carry no parser-relevant data.
 13→var droppedTypes = map[string]bool{
 14→	"progress":              true,
 15→	"file-history-snapshot": true,
 16→	"queue-operation":       true,
 17→	"system":                true,
 18→}
 19→
 20→// Options provides metadata fields written to every output line.
 21→type Options struct {
 22→	Agent      string // e.g. "claude-code"
 23→	CLIVersion string // e.g. "0.42.0"
 24→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 25→}
 26→
 27→// compactMeta holds pre-computed JSON fragments for fields that are identical
 28→// on every output line, avoiding repeated marshaling.
 29→type compactMeta struct {
 30→	v          json.RawMessage
 31→	agent      json.RawMessage
 32→	cliVersion json.RawMessage
 33→}
 34→
 35→func newCompactMeta(opts Options) compactMeta {
 36→	return compactMeta{
 37→		v:          mustMarshal(1),
 38→		agent:      mustMarshal(opts.Agent),
 39→		cliVersion: mustMarshal(opts.CLIVersion),
 40→	}
 41→}
 42→
 43→// Compact converts a full.jsonl transcript into the transcript.jsonl format.
 44→//
 45→// The output format puts version, agent, and cli_version on every line,
 46→// flattens the message wrapper, and splits user tool results into separate entries:
 47→//
 48→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 49→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 50→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 51→func Compact(content []byte, opts Options) ([]byte, error) {
 52→	truncated := sliceFromLine(content, opts.StartLine)
 53→	if truncated == nil {
 54→		truncated = []byte{}
 55→	}
 56→
 57→	if isOpenCodeFormat(truncated) {
 58→		return compactOpenCode(truncated, opts)
 59→	}
 60→
 61→	if isGeminiFormat(truncated) {
 62→		return compactGemini(truncated, opts)
 63→	}
 64→
 65→	return compactJSONL(truncated, opts)
 66→}
 67→
 68→// sliceFromLine returns the content starting from line number startLine (0-indexed).
 69→// This is used to extract only the checkpoint-specific portion of a cumulative transcript.
 70→// Returns empty slice if startLine exceeds the number of lines.
 71→func sliceFromLine(content []byte, startLine int) []byte {
 72→	if len(content) == 0 || startLine <= 0 {
 73→		return content
 74→	}
 75→
 76→	lineCount := 0
 77→	offset := 0
 78→	for i, b := range content {
 79→		if b == '\n' {
 80→			lineCount++
 81→			if lineCount == startLine {
 82→				offset = i + 1
 83→				break
 84→			}
 85→		}
 86→	}
 87→
 88→	if lineCount < startLine {
 89→		return nil
 90→	}
 91→
 92→	if offset >= len(content) {
 93→		return nil
 94→	}
 95→
 96→	return content[offset:]
 97→}
 98→
 99→// marshalOrdered produces a JSON object with keys in the given order.
100→// Pairs with nil values are omitted.
101→func marshalOrdered(pairs ...interface{}) []byte {
102→	var buf bytes.Buffer
103→	buf.WriteByte('{')
104→	first := true
105→	for i := 0; i < len(pairs)-1; i += 2 {
106→		key := pairs[i].(string)               //nolint:errcheck,forcetypeassert // contract: keys are always strings
107→		val, _ := pairs[i+1].(json.RawMessage) //nolint:errcheck // nil val is handled below
108→		if val == nil {
109→			continue
110→		}
111→		if !first {
112→			buf.WriteByte(',')
113→		}
114→		keyJSON, _ := json.Marshal(key) //nolint:errcheck,errchkjson // string keys never fail
115→		buf.Write(keyJSON)
116→		buf.WriteByte(':')
117→		buf.Write(val)
118→		first = false
119→	}
120→	buf.WriteByte('}')
121→	return buf.Bytes()
122→}
123→
124→// mustMarshal marshals v to JSON, panicking on error (which should never
125→// happen for the primitive types we pass).
126→func mustMarshal(v interface{}) json.RawMessage {
127→	b, _ := json.Marshal(v) //nolint:errcheck,errchkjson // only used with primitive types that never fail
128→	return b
129→}
130→
131→// copyField copies a single key from src to dst if it exists.
132→func copyField(dst, src map[string]json.RawMessage, key string) {
133→	if v, ok := src[key]; ok {
134→		dst[key] = v
135→	}
136→}
137→
138→// unquote JSON-decodes a raw message as a string. Returns "" on failure.
139→func unquote(raw json.RawMessage) string {
140→	var s string
141→	if json.Unmarshal(raw, &s) == nil {
142→		return s
143→	}
144→	return ""
145→}
