 12→
 13→// --- OpenCode format support ---
 14→//
 15→// OpenCode transcripts are a single JSON object (not JSONL):
 16→//
 17→//	{"info":{...},"messages":[{"info":{"role":"user","time":{...}},"parts":[...]}, ...]}
 18→//
 19→// Parts use "type" values: "text", "tool", "step-start", "step-finish".
 20→// Tool parts store the tool name in "tool" (string) and call details in "state".
 21→
 22→// isOpenCodeFormat checks whether content is a single JSON object with the
 23→// OpenCode session shape (top-level "info" and "messages" keys).
 24→func isOpenCodeFormat(content []byte) bool {
 25→	trimmed := bytes.TrimSpace(content)
 26→	if len(trimmed) == 0 || trimmed[0] != '{' {
 27→		return false
 28→	}
 29→	// Quick structural check: unmarshal just enough to detect the keys.
 30→	var probe struct {
 31→		Info     *json.RawMessage `json:"info"`
 32→		Messages *json.RawMessage `json:"messages"`
 33→	}
 34→	if json.Unmarshal(trimmed, &probe) != nil {
 35→		return false
 36→	}
 37→	return probe.Info != nil && probe.Messages != nil
 38→}
 39→
 40→// openCodeMessage mirrors the OpenCode message structure for unmarshaling.
 41→type openCodeMessage struct {
 42→	Info  openCodeMessageInfo          `json:"info"`
 43→	Parts []map[string]json.RawMessage `json:"parts"`
 44→}
 45→
 46→type openCodeMessageInfo struct {
 47→	ID   string          `json:"id"`
 48→	Role string          `json:"role"`
 49→	Time openCodeMsgTime `json:"time"`
 50→}
 51→
 52→type openCodeMsgTime struct {
 53→	Created   int64 `json:"created"`
 54→	Completed int64 `json:"completed"`
 55→}
 56→
 57→// compactOpenCode converts a full OpenCode session JSON into transcript lines.
 58→func compactOpenCode(content []byte, opts Options) ([]byte, error) {
 59→	var session struct {
 60→		Messages []openCodeMessage `json:"messages"`
 61→	}
 62→	if err := json.Unmarshal(bytes.TrimSpace(content), &session); err != nil {
 63→		return nil, fmt.Errorf("parsing opencode session: %w", err)
 64→	}
 65→
 66→	meta := newCompactMeta(opts)
 67→	var result []byte
 68→
 69→	for _, msg := range session.Messages {
 70→		ts := msToTimestamp(msg.Info.Time.Created)
 71→
 72→		switch msg.Info.Role {
 73→		case transcript.TypeUser:
 74→			lines := convertOpenCodeUser(msg, ts, meta)
 75→			for _, l := range lines {
 76→				result = append(result, l...)
 77→				result = append(result, '\n')
 78→			}
 79→		case transcript.TypeAssistant:
 80→			lines := convertOpenCodeAssistant(msg, ts, meta)
 81→			for _, l := range lines {
 82→				result = append(result, l...)
 83→				result = append(result, '\n')
 84→			}
 85→		}
 86→	}
 87→
 88→	return result, nil
 89→}
 90→
 91→func convertOpenCodeUser(msg openCodeMessage, ts json.RawMessage, meta compactMeta) [][]byte {
 92→	content := make([]map[string]json.RawMessage, 0, len(msg.Parts))
 93→
 94→	for _, part := range msg.Parts {
 95→		if unquote(part["type"]) != transcript.ContentTypeText {
 96→			continue
 97→		}
 98→		text := textutil.StripIDEContextTags(unquote(part[transcript.ContentTypeText]))
 99→		if text == "" {
100→			continue
101→		}
102→		block := map[string]json.RawMessage{
103→			"text": mustMarshal(text),
104→		}
105→		if id := part["id"]; id != nil {
106→			block["id"] = id
107→		}
108→		content = append(content, block)
109→	}
110→
111→	contentJSON, err := json.Marshal(content)
112→	if err != nil {
113→		return nil
114→	}
115→
116→	b := marshalOrdered(
117→		"v", meta.v,
118→		"agent", meta.agent,
119→		"cli_version", meta.cliVersion,
120→		"type", mustMarshal(transcript.TypeUser),
121→		"ts", ts,
122→		"content", json.RawMessage(contentJSON),
123→	)
124→	if b == nil {
125→		return nil
126→	}
127→	return [][]byte{b}
128→}
129→
130→func convertOpenCodeAssistant(msg openCodeMessage, ts json.RawMessage, meta compactMeta) [][]byte {
131→	content := make([]map[string]json.RawMessage, 0, len(msg.Parts))
132→
133→	for _, part := range msg.Parts {
134→		partType := unquote(part["type"])
135→
136→		switch partType {
137→		case transcript.ContentTypeText:
138→			content = append(content, map[string]json.RawMessage{
139→				"type": mustMarshal(transcript.ContentTypeText),
140→				"text": part[transcript.ContentTypeText],
141→			})
142→		case "tool":
143→			toolBlock := make(map[string]json.RawMessage)
144→			toolBlock["type"] = mustMarshal(transcript.ContentTypeToolUse)
145→			if callID := part["callID"]; callID != nil {
146→				toolBlock["id"] = callID
147→			}
148→			// "tool" field is the tool name (string).
149→			if toolName := part["tool"]; toolName != nil {
150→				toolBlock["name"] = toolName
151→			}
152→			// Extract input and result from state if available.
153→			if stateRaw := part["state"]; stateRaw != nil {
154→				var state map[string]json.RawMessage
155→				if json.Unmarshal(stateRaw, &state) == nil {
156→					if inp := state["input"]; inp != nil {
157→						toolBlock["input"] = inp
158→					}
159→					toolBlock["result"] = openCodeToolResult(state)
160→				}
161→			}
162→			content = append(content, toolBlock)
163→			// step-start, step-finish carry no transcript-relevant data.
164→		}
165→	}
166→
167→	contentJSON, err := json.Marshal(content)
168→	if err != nil {
169→		return nil
170→	}
171→
172→	b := marshalOrdered(
173→		"v", meta.v,
174→		"agent", meta.agent,
175→		"cli_version", meta.cliVersion,
176→		"type", mustMarshal(transcript.TypeAssistant),
177→		"ts", ts,
178→		"id", mustMarshal(msg.Info.ID),
179→		"content", json.RawMessage(contentJSON),
180→	)
181→	if b == nil {
182→		return nil
183→	}
184→	return [][]byte{b}
185→}
186→
187→// openCodeToolResult builds the compact {"output":"...","status":"done"|"error"}
188→// object from an OpenCode tool state map.
189→func openCodeToolResult(state map[string]json.RawMessage) json.RawMessage {
190→	status := "done"
191→	if s := unquote(state["status"]); s != "" && s != "completed" {
192→		status = "error"
193→	}
194→	result := map[string]string{
195→		"output": unquote(state["output"]),
196→		"status": status,
197→	}
198→	return mustMarshal(result)
199→}
200→
201→// msToTimestamp converts a Unix millisecond timestamp to an RFC3339 JSON string.
202→func msToTimestamp(ms int64) json.RawMessage {
203→	if ms == 0 {
204→		return nil
205→	}
206→	t := time.UnixMilli(ms).UTC()
207→	return mustMarshal(t.Format(time.RFC3339Nano))
208→}
