  1→// Package compact converts full.jsonl transcripts into a normalized,
  2→// compact transcript.jsonl format. Each agent format (Claude Code JSONL,
  3→// OpenCode JSON, Gemini, Factory AI Droid) has its own converter file;
  4→// this file holds the shared entry point and helper utilities.
  5→package compact
  6→
  7→import (
  8→	"bytes"
  9→	"encoding/json"
 10→)
 11→
 12→// Options provides metadata fields written to every output line.
 13→type Options struct {
 14→	Agent      string // e.g. "claude-code"
 15→	CLIVersion string // e.g. "0.42.0"
 16→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 17→}
 18→
 19→// compactMeta holds pre-computed JSON fragments for fields that are identical
 20→// on every output line, avoiding repeated marshaling.
 21→type compactMeta struct {
 22→	v          json.RawMessage
 23→	agent      json.RawMessage
 24→	cliVersion json.RawMessage
 25→}
 26→
 27→func newCompactMeta(opts Options) compactMeta {
 28→	return compactMeta{
 29→		v:          mustMarshal(1),
 30→		agent:      mustMarshal(opts.Agent),
 31→		cliVersion: mustMarshal(opts.CLIVersion),
 32→	}
 33→}
 34→
 35→// Compact converts a full.jsonl transcript into the transcript.jsonl format.
 36→//
 37→// The output format puts version, agent, and cli_version on every line,
 38→// flattens the message wrapper, and splits user tool results into separate entries:
 39→//
 40→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 41→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 42→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 43→func Compact(content []byte, opts Options) ([]byte, error) {
 44→	truncated := sliceFromLine(content, opts.StartLine)
 45→	if truncated == nil {
 46→		truncated = []byte{}
 47→	}
 48→
 49→	if isOpenCodeFormat(truncated) {
 50→		return compactOpenCode(truncated, opts)
 51→	}
 52→
 53→	if isGeminiFormat(truncated) {
 54→		return compactGemini(truncated, opts)
 55→	}
 56→
 57→	return compactJSONL(truncated, opts)
 58→}
 59→
 60→// sliceFromLine returns the content starting from line number startLine (0-indexed).
 61→// This is used to extract only the checkpoint-specific portion of a cumulative transcript.
 62→// Returns empty slice if startLine exceeds the number of lines.
 63→func sliceFromLine(content []byte, startLine int) []byte {
 64→	if len(content) == 0 || startLine <= 0 {
 65→		return content
 66→	}
 67→
 68→	lineCount := 0
 69→	offset := 0
 70→	for i, b := range content {
 71→		if b == '\n' {
 72→			lineCount++
 73→			if lineCount == startLine {
 74→				offset = i + 1
 75→				break
 76→			}
 77→		}
 78→	}
 79→
 80→	if lineCount < startLine {
 81→		return nil
 82→	}
 83→
 84→	if offset >= len(content) {
 85→		return nil
 86→	}
 87→
 88→	return content[offset:]
 89→}
 90→
 91→// marshalOrdered produces a JSON object with keys in the given order.
 92→// Pairs with nil values are omitted.
 93→func marshalOrdered(pairs ...interface{}) []byte {
 94→	var buf bytes.Buffer
 95→	buf.WriteByte('{')
 96→	first := true
 97→	for i := 0; i < len(pairs)-1; i += 2 {
 98→		key := pairs[i].(string)               //nolint:errcheck,forcetypeassert // contract: keys are always strings
 99→		val, _ := pairs[i+1].(json.RawMessage) //nolint:errcheck // nil val is handled below
100→		if val == nil {
101→			continue
102→		}
103→		if !first {
104→			buf.WriteByte(',')
105→		}
106→		keyJSON, _ := json.Marshal(key) //nolint:errcheck,errchkjson // string keys never fail
107→		buf.Write(keyJSON)
108→		buf.WriteByte(':')
109→		buf.Write(val)
110→		first = false
111→	}
112→	buf.WriteByte('}')
113→	return buf.Bytes()
114→}
115→
116→// mustMarshal marshals v to JSON, panicking on error (which should never
117→// happen for the primitive types we pass).
118→func mustMarshal(v interface{}) json.RawMessage {
119→	b, _ := json.Marshal(v) //nolint:errcheck,errchkjson // only used with primitive types that never fail
120→	return b
121→}
122→
123→// copyField copies a single key from src to dst if it exists.
124→func copyField(dst, src map[string]json.RawMessage, key string) {
125→	if v, ok := src[key]; ok {
126→		dst[key] = v
127→	}
128→}
129→
130→// unquote JSON-decodes a raw message as a string. Returns "" on failure.
131→func unquote(raw json.RawMessage) string {
132→	var s string
133→	if json.Unmarshal(raw, &s) == nil {
134→		return s
135→	}
136→	return ""
137→}
