 76→	for _, line := range strings.Split(string(data), "\n") {
 77→		if strings.TrimSpace(line) != "" {
 78→			lines = append(lines, line)
 79→		}
 80→	}
 81→	return lines
 82→}
 83→
 84→// assertJSONLines compares actual output lines against expected JSON strings,
 85→// using semantic JSON equality (order-independent for object keys).
 86→func assertJSONLines(t *testing.T, actual []byte, expected []string) {
 87→	t.Helper()
 88→
 89→	actualLines := nonEmptyLines(actual)
 90→
 91→	if len(expected) == 0 && len(actualLines) == 0 {
 92→		return
 93→	}
 94→
 95→	if len(actualLines) != len(expected) {
 96→		t.Fatalf("line count mismatch: got %d, want %d\nactual:\n%s", len(actualLines), len(expected), string(actual))
 97→	}
 98→
 99→	for i := range expected {
100→		var got, want interface{}
101→		if err := json.Unmarshal([]byte(actualLines[i]), &got); err != nil {
102→			t.Fatalf("line %d: failed to parse actual JSON: %v\nline: %s", i, err, actualLines[i])
103→		}
104→		if err := json.Unmarshal([]byte(expected[i]), &want); err != nil {
105→			t.Fatalf("line %d: failed to parse expected JSON: %v\nline: %s", i, err, expected[i])
106→		}
107→		if !reflect.DeepEqual(got, want) {
108→			prettyGot, _ := json.MarshalIndent(got, "", "  ")   //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
109→			prettyWant, _ := json.MarshalIndent(want, "", "  ") //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
110→			t.Errorf("line %d mismatch:\ngot:\n%s\nwant:\n%s", i, prettyGot, prettyWant)
111→		}
112→	}
113→}
