 35→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 36→// transcript line. It checks the "type" field, then falls back to "role".
 37→// Returns "" for unrecognised or dropped entries.
 38→func normalizeKind(raw map[string]json.RawMessage) string {
 39→	kind := unquote(raw["type"])
 40→	if kind == "" {
 41→		kind = unquote(raw["role"])
 42→	}
 43→
 44→	if droppedTypes[kind] {
 45→		return ""
 46→	}
 47→	if userAliases[kind] {
 48→		return transcript.TypeUser
 49→	}
 50→	if assistantAliases[kind] {
 51→		return transcript.TypeAssistant
 52→	}
