 56→// compactJSONL converts JSONL transcripts (Claude Code, Cursor, Factory AI Droid)
 57→// into the compact transcript format, one line at a time.
 58→// Factory AI Droid lines are unwrapped by unwrapEnvelope (droid.go) before conversion.
 59→func compactJSONL(content []byte, opts Options) ([]byte, error) {
 60→	meta := newCompactMeta(opts)
 61→	reader := bufio.NewReader(bytes.NewReader(content))
 62→	var result []byte
 63→
 64→	for {
 65→		lineBytes, err := reader.ReadBytes('\n')
 66→		if err != nil && err != io.EOF {
 67→			return nil, fmt.Errorf("reading JSONL line: %w", err)
 68→		}
 69→
 70→		if len(bytes.TrimSpace(lineBytes)) > 0 {
 71→			outputLines := convertLine(lineBytes, meta)
 72→			for _, ol := range outputLines {
 73→				result = append(result, ol...)
 74→				result = append(result, '\n')
 75→			}
 76→		}
 77→
 78→		if err == io.EOF {
 79→			break
 80→		}
 81→	}
 82→
 83→	return result, nil
 84→}
 85→
 86→// convertLine converts a single full.jsonl line into zero or more transcript.jsonl lines.
 87→func convertLine(lineBytes []byte, meta compactMeta) [][]byte {
 88→	var raw map[string]json.RawMessage
 89→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
 90→		return nil
 91→	}
 92→
 93→	raw = unwrapEnvelope(raw)
 94→
 95→	switch normalizeKind(raw) {
 96→	case transcript.TypeAssistant:
 97→		return convertAssistant(raw, meta)
 98→	case transcript.TypeUser:
 99→		return convertUser(raw, meta)
100→	default:
101→		return nil
102→	}
103→}
104→
105→func convertAssistant(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
106→	var id, content json.RawMessage
107→	if msg := parseMessage(raw); msg != nil {
108→		id = msg["id"]
109→		if contentRaw, ok := msg["content"]; ok {
110→			content = stripAssistantContent(contentRaw)
111→		}
112→	}
113→
114→	b := marshalOrdered(
115→		"v", meta.v,
116→		"agent", meta.agent,
117→		"cli_version", meta.cliVersion,
118→		"type", mustMarshal(transcript.TypeAssistant),
119→		"ts", raw["timestamp"],
120→		"id", id,
121→		"content", content,
122→	)
123→	if b == nil {
124→		return nil
125→	}
126→	return [][]byte{b}
127→}
128→
129→func convertUser(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
130→	var lines [][]byte
131→	ts := raw["timestamp"]
132→
133→	var textContent string
134→	var toolResults []toolResultEntry
135→
136→	if msg := parseMessage(raw); msg != nil {
137→		if contentRaw, ok := msg["content"]; ok {
138→			textContent, toolResults = extractUserContent(contentRaw)
139→		}
140→	}
141→
142→	b := marshalOrdered(
143→		"v", meta.v,
144→		"agent", meta.agent,
145→		"cli_version", meta.cliVersion,
146→		"type", mustMarshal(transcript.TypeUser),
147→		"ts", ts,
148→		"content", mustMarshal(textContent),
149→	)
150→	if b != nil {
151→		lines = append(lines, b)
152→	}
153→
154→	// full.jsonl has a single toolUseResult per user entry, not one per tool_use_id.
155→	// When there are multiple tool_result blocks, each user_tool_result line gets the
156→	// same minimized result — a known limitation of the source format.
157→	var minimizedResult json.RawMessage
158→	if turRaw, ok := raw["toolUseResult"]; ok {
159→		minimizedResult = minimizeToolUseResult(turRaw)
160→	}
161→
162→	for _, tr := range toolResults {
163→		result := minimizedResult
164→		if result == nil {
165→			result = mustMarshal(map[string]interface{}{})
166→		}
167→
168→		b := marshalOrdered(
169→			"v", meta.v,
170→			"agent", meta.agent,
171→			"cli_version", meta.cliVersion,
172→			"type", mustMarshal("user_tool_result"),
173→			"ts", ts,
174→			"tool_use_id", mustMarshal(tr.toolUseID),
175→			"result", result,
176→		)
177→		if b != nil {
178→			lines = append(lines, b)
179→		}
180→	}
181→
182→	return lines
183→}
