 1→package compact
 2→
 3→import "encoding/json"
 4→
 5→// unwrapEnvelope handles envelope formats where the actual message is nested.
 6→// Factory AI Droid uses {"type":"message","message":{"role":"user","content":...}}.
 7→// If the line is an envelope, it promotes inner fields (role, content) to the top
 8→// level and carries over outer fields (timestamp, id) so converters see a flat structure.
 9→// Otherwise it returns raw unchanged.
10→func unwrapEnvelope(raw map[string]json.RawMessage) map[string]json.RawMessage {
11→	if unquote(raw["type"]) != "message" {
12→		return raw
13→	}
14→
15→	msgRaw, ok := raw["message"]
16→	if !ok {
17→		return raw
18→	}
19→
20→	var inner map[string]json.RawMessage
21→	if json.Unmarshal(msgRaw, &inner) != nil {
22→		return raw
23→	}
24→
25→	innerRole := unquote(inner["role"])
26→	if !userAliases[innerRole] && !assistantAliases[innerRole] {
27→		return raw
28→	}
29→
30→	// Merge outer → inner: outer timestamp/id as defaults, inner fields override.
31→	merged := make(map[string]json.RawMessage, len(inner)+3)
32→	if v, has := raw["timestamp"]; has {
33→		merged["timestamp"] = v
34→	}
35→	if v, has := raw["id"]; has {
36→		merged["id"] = v
37→	}
38→	for k, v := range inner {
39→		merged[k] = v
40→	}
41→	// Promote "role" to "type" so normalizeKind resolves it.
42→	if _, hasType := merged["type"]; !hasType {
43→		merged["type"] = inner["role"]
44→	}
45→	// Keep "message" so converters can extract nested content.
46→	merged["message"] = msgRaw
47→
48→	return merged
49→}
