  1→// Package compact converts full.jsonl transcripts into a normalized,
  2→// compact transcript.jsonl format. Each agent format has its own converter:
  3→//
  4→//   - jsonl.go:     JSONL-based agents (Claude Code, Cursor, Factory AI Droid)
  5→//   - droid.go:     Factory AI Droid envelope unwrapping (preprocessing for jsonl.go)
  6→//   - gemini.go:    Gemini CLI (single JSON object with "gemini" message type)
  7→//   - opencode.go:  OpenCode (single JSON object with parts-based messages)
  8→//
  9→// This file holds the shared entry point, format detection, and helper utilities.
 10→package compact
 11→
 12→import (
 13→	"bytes"
 14→	"encoding/json"
 15→)
 16→
 17→// Options provides metadata fields written to every output line.
 18→type Options struct {
 19→	Agent      string // e.g. "claude-code"
 20→	CLIVersion string // e.g. "0.42.0"
 21→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 22→}
 23→
 24→// compactMeta holds pre-computed JSON fragments for fields that are identical
 25→// on every output line, avoiding repeated marshaling.
 26→type compactMeta struct {
 27→	v          json.RawMessage
 28→	agent      json.RawMessage
 29→	cliVersion json.RawMessage
 30→}
 31→
 32→func newCompactMeta(opts Options) compactMeta {
 33→	return compactMeta{
 34→		v:          mustMarshal(1),
 35→		agent:      mustMarshal(opts.Agent),
 36→		cliVersion: mustMarshal(opts.CLIVersion),
 37→	}
 38→}
 39→
 40→// Compact converts a full.jsonl transcript into the transcript.jsonl format.
 41→//
 42→// The output format puts version, agent, and cli_version on every line,
 43→// flattens the message wrapper, and splits user tool results into separate entries:
 44→//
 45→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 46→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 47→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 48→func Compact(content []byte, opts Options) ([]byte, error) {
 49→	truncated := sliceFromLine(content, opts.StartLine)
 50→	if truncated == nil {
 51→		truncated = []byte{}
 52→	}
 53→
 54→	if isOpenCodeFormat(truncated) {
 55→		return compactOpenCode(truncated, opts)
 56→	}
 57→
 58→	if isGeminiFormat(truncated) {
 59→		return compactGemini(truncated, opts)
 60→	}
 61→
 62→	return compactJSONL(truncated, opts)
 63→}
 64→
 65→// sliceFromLine returns the content starting from line number startLine (0-indexed).
 66→// This is used to extract only the checkpoint-specific portion of a cumulative transcript.
 67→// Returns empty slice if startLine exceeds the number of lines.
 68→func sliceFromLine(content []byte, startLine int) []byte {
 69→	if len(content) == 0 || startLine <= 0 {
 70→		return content
 71→	}
 72→
 73→	lineCount := 0
 74→	offset := 0
 75→	for i, b := range content {
 76→		if b == '\n' {
 77→			lineCount++
 78→			if lineCount == startLine {
 79→				offset = i + 1
 80→				break
 81→			}
 82→		}
 83→	}
 84→
 85→	if lineCount < startLine {
 86→		return nil
 87→	}
 88→
 89→	if offset >= len(content) {
 90→		return nil
 91→	}
 92→
 93→	return content[offset:]
 94→}
 95→
 96→// marshalOrdered produces a JSON object with keys in the given order.
 97→// Pairs with nil values are omitted.
 98→func marshalOrdered(pairs ...interface{}) []byte {
 99→	var buf bytes.Buffer
100→	buf.WriteByte('{')
101→	first := true
102→	for i := 0; i < len(pairs)-1; i += 2 {
103→		key := pairs[i].(string)               //nolint:errcheck,forcetypeassert // contract: keys are always strings
104→		val, _ := pairs[i+1].(json.RawMessage) //nolint:errcheck // nil val is handled below
105→		if val == nil {
106→			continue
107→		}
108→		if !first {
109→			buf.WriteByte(',')
110→		}
111→		keyJSON, _ := json.Marshal(key) //nolint:errcheck,errchkjson // string keys never fail
112→		buf.Write(keyJSON)
113→		buf.WriteByte(':')
114→		buf.Write(val)
115→		first = false
116→	}
117→	buf.WriteByte('}')
118→	return buf.Bytes()
119→}
120→
121→// mustMarshal marshals v to JSON, panicking on error (which should never
122→// happen for the primitive types we pass).
123→func mustMarshal(v interface{}) json.RawMessage {
124→	b, _ := json.Marshal(v) //nolint:errcheck,errchkjson // only used with primitive types that never fail
125→	return b
126→}
127→
128→// copyField copies a single key from src to dst if it exists.
129→func copyField(dst, src map[string]json.RawMessage, key string) {
130→	if v, ok := src[key]; ok {
131→		dst[key] = v
132→	}
133→}
134→
135→// unquote JSON-decodes a raw message as a string. Returns "" on failure.
136→func unquote(raw json.RawMessage) string {
137→	var s string
138→	if json.Unmarshal(raw, &s) == nil {
139→		return s
140→	}
141→	return ""
142→}
