411→// sliceFromLine returns the content starting from line number startLine (0-indexed).
412→// This is used to extract only the checkpoint-specific portion of a cumulative transcript.
413→// Returns empty slice if startLine exceeds the number of lines.
414→func sliceFromLine(content []byte, startLine int) []byte {
415→	if len(content) == 0 || startLine <= 0 {
416→		return content
417→	}
418→
419→	lineCount := 0
420→	offset := 0
421→	for i, b := range content {
422→		if b == '\n' {
423→			lineCount++
424→			if lineCount == startLine {
425→				offset = i + 1
426→				break
427→			}
428→		}
429→	}
430→
431→	if lineCount < startLine {
432→		return nil
433→	}
434→
435→	if offset >= len(content) {
436→		return nil
437→	}
438→
