442→// marshalOrdered produces a JSON object with keys in the given order.
443→// Pairs with nil values are omitted.
444→func marshalOrdered(pairs ...interface{}) []byte {
445→	var buf bytes.Buffer
446→	buf.WriteByte('{')
447→	first := true
448→	for i := 0; i < len(pairs)-1; i += 2 {
449→		key := pairs[i].(string)               //nolint:errcheck,forcetypeassert // contract: keys are always strings
450→		val, _ := pairs[i+1].(json.RawMessage) //nolint:errcheck // nil val is handled below
451→		if val == nil {
452→			continue
453→		}
454→		if !first {
455→			buf.WriteByte(',')
456→		}
457→		keyJSON, _ := json.Marshal(key) //nolint:errcheck,errchkjson // string keys never fail
458→		buf.Write(keyJSON)
459→		buf.WriteByte(':')
460→		buf.Write(val)
461→		first = false
462→	}
463→	buf.WriteByte('}')
464→	return buf.Bytes()
465→}
