241→// parseMessage extracts and parses the "message" field from a JSONL transcript
242→// line. All JSONL agents nest content inside a "message" object.
243→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
244→	msgRaw, ok := raw["message"]
245→	if !ok {
246→		return nil
247→	}
248→	var msg map[string]json.RawMessage
249→	if json.Unmarshal(msgRaw, &msg) == nil {
250→		return msg
251→	}
252→	return nil
253→}
