255→// extractUserContent separates user message content into text and tool_result entries.
256→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
257→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
258→	var str string
259→	if json.Unmarshal(contentRaw, &str) == nil {
260→		return textutil.StripIDEContextTags(str), nil
261→	}
262→
263→	var blocks []map[string]json.RawMessage
264→	if json.Unmarshal(contentRaw, &blocks) != nil {
265→		return "", nil
266→	}
267→
268→	var texts []string
269→	var toolResults []toolResultEntry
270→
271→	for _, block := range blocks {
272→		blockType := unquote(block["type"])
273→
274→		if blockType == "tool_result" {
275→			toolResults = append(toolResults, toolResultEntry{
276→				toolUseID: unquote(block["tool_use_id"]),
277→			})
278→			continue
279→		}
280→
281→		if blockType == transcript.ContentTypeText {
282→			stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
283→			if stripped != "" {
284→				texts = append(texts, stripped)
285→			}
286→		}
287→	}
