292→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
293→	var str string
294→	if json.Unmarshal(contentRaw, &str) == nil {
295→		return contentRaw
296→	}
297→
298→	var blocks []map[string]json.RawMessage
299→	if json.Unmarshal(contentRaw, &blocks) != nil {
300→		return contentRaw
301→	}
302→
303→	result := make([]map[string]json.RawMessage, 0, len(blocks))
304→	for _, block := range blocks {
305→		blockType := unquote(block["type"])
306→
307→		if blockType == "thinking" || blockType == "redacted_thinking" {
308→			continue
309→		}
310→
311→		if blockType == transcript.ContentTypeToolUse {
312→			stripped := make(map[string]json.RawMessage)
313→			copyField(stripped, block, "type")
314→			copyField(stripped, block, "id")
315→			copyField(stripped, block, "name")
316→			copyField(stripped, block, "input")
317→			result = append(result, stripped)
318→			continue
319→		}
320→
321→		result = append(result, block)
322→	}
323→
324→	b, err := json.Marshal(result)
325→	if err != nil {
326→		return contentRaw
327→	}
328→	return b
329→}
