331→// minimizeToolUseResult keeps only fields needed for replaying tool calls
332→// (type, file metadata, error, answers). Output text and other verbose
333→// fields are dropped to reduce transcript size.
334→func minimizeToolUseResult(raw json.RawMessage) json.RawMessage {
335→	var obj map[string]json.RawMessage
336→	if json.Unmarshal(raw, &obj) != nil {
337→		return raw
338→	}
339→
340→	return marshalOrdered(
341→		"type", obj["type"],
342→		"file", obj["file"],
343→		"error", obj["error"],
344→		"answers", obj["answers"],
345→	)
346→}
347→
348→// ---------------------------------------------------------------------------
349→// Shared helpers
350→// ---------------------------------------------------------------------------
351→
352→// sliceFromLine returns the content starting from line number startLine (0-indexed).
353→// This is used to extract only the checkpoint-specific portion of a cumulative transcript.
354→// Returns empty slice if startLine exceeds the number of lines.
355→func sliceFromLine(content []byte, startLine int) []byte {
356→	if len(content) == 0 || startLine <= 0 {
357→		return content
358→	}
359→
360→	lineCount := 0
361→	offset := 0
362→	for i, b := range content {
363→		if b == '\n' {
364→			lineCount++
365→			if lineCount == startLine {
366→				offset = i + 1
367→				break
368→			}
369→		}
370→	}
371→
372→	if lineCount < startLine {
373→		return nil
374→	}
375→
376→	if offset >= len(content) {
377→		return nil
378→	}
379→
380→	return content[offset:]
381→}
382→
383→// marshalOrdered produces a JSON object with keys in the given order.
384→// Pairs with nil values are omitted.
385→func marshalOrdered(pairs ...interface{}) []byte {
386→	var buf bytes.Buffer
387→	buf.WriteByte('{')
388→	first := true
389→	for i := 0; i < len(pairs)-1; i += 2 {
390→		key := pairs[i].(string)               //nolint:errcheck,forcetypeassert // contract: keys are always strings
391→		val, _ := pairs[i+1].(json.RawMessage) //nolint:errcheck // nil val is handled below
392→		if val == nil {
393→			continue
394→		}
395→		if !first {
396→			buf.WriteByte(',')
397→		}
398→		keyJSON, _ := json.Marshal(key) //nolint:errcheck,errchkjson // string keys never fail
399→		buf.Write(keyJSON)
400→		buf.WriteByte(':')
401→		buf.Write(val)
402→		first = false
403→	}
404→	buf.WriteByte('}')
405→	return buf.Bytes()
406→}
407→
408→// mustMarshal marshals v to JSON, panicking on error (which should never
409→// happen for the primitive types we pass).
410→func mustMarshal(v interface{}) json.RawMessage {
411→	b, _ := json.Marshal(v) //nolint:errcheck,errchkjson // only used with primitive types that never fail
412→	return b
413→}
414→
415→// copyField copies a single key from src to dst if it exists.
416→func copyField(dst, src map[string]json.RawMessage, key string) {
417→	if v, ok := src[key]; ok {
418→		dst[key] = v
419→	}
420→}
421→
422→// unquote JSON-decodes a raw message as a string. Returns "" on failure.
423→func unquote(raw json.RawMessage) string {
424→	var s string
425→	if json.Unmarshal(raw, &s) == nil {
426→		return s
427→	}
428→	return ""
429→}
